use std::ffi::c_int;
use std::path::Path;

const JVMTI_VERSION_BASE: c_int = 0x3000_0000;

fn main() {
	println!("cargo:rerun-if-env-changed=JAVA_VERSION");

	let Ok(java_version) = std::env::var("JAVA_VERSION") else {
		panic!("`JAVA_VERSION` environment variable must be set")
	};

	let version_path = Path::new(&std::env::var("CARGO_MANIFEST_DIR").unwrap())
		.join("src")
		.join("version.rs");
	let version_fn = format!(
		r"#![allow(clippy::all, clippy::pedantic)]
/// Current JVMTI version. Do not modify, generated by `build.rs`
pub(crate) const fn jvmti_version() -> core::ffi::c_int {{
    {JVMTI_VERSION_BASE:#X} + ({java_version} * 0x10000)
}}
"
	);

	std::fs::write(version_path, version_fn).unwrap();
}
